{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table izf-wh.maplemonk.izf_returns_consolidated_intermediate as select e.reference_code ,e.saleorderitemcode ,e.ORDER_ID ,Upper(e.order_status) as order_status ,cast(e.ORDER_DATE as datetime) AS Order_Date ,cast(DELIVERED_DATE as datetime) as Delivered_Date ,UPPER(e.marketplace) AS marketplace ,UPPER(e.marketplace) AS MARKETING_CHANNEL ,UPPER(e.marketplace) AS SOURCE ,UPPER(e.PRODUCT_NAME_final) AS PRODUCT_NAME ,e.SKU ,e.sku as commonsku ,e.SKU_STYLE ,e.SKU_SIZE ,UPPER(CAST(e.product_category AS STRING)) AS product_category ,UPPER(CAST(e.product_sub_category AS STRING)) AS product_sub_category ,e.quantity as order_quantity ,UPPER(e.CITY) AS City ,UPPER(e.STATE) AS State ,e.pincode ,UPPER(e.COURIER) AS Shipping_Courier ,e.awb ,e.name AS NAME ,e.email AS EMAIL ,cast(null as string) as return_request_number ,cast(return_initiated_date as datetime) as original_return_request_date ,cast(null as int64) as no_of_return_requests_initiated ,cast(null as array<string>) as list_of_pickup_couriers_assigned ,cast(null as datetime) as return_approved_date ,cast(null as datetime) as return_refunded_at ,cast(null as datetime) as return_inspected_date ,cast(r.return_date as datetime) as return_date ,case when coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) = 1 then \'Approved\' else null end as return_approval_status ,case when lower(r.return_type) like \'%courier%\' or lower(r.seller_return_reason) like \'%rto%\' or lower(r. seller_return_reason) like \'%cancel%\' then \'RTO\' when lower(r.Return_Type) like \'%customer%\' then \'return\' when coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) = 1 then \'return\' when lower(r.channel_return_reason) like \'%lost%\' then \'lost\' when lower(r.seller_return_reason) is not null then \'return\' else null end as return_request_type , case when lower(r.return_type) like \'%courier%\' or lower(r.seller_return_reason) like \'%rto%\' or lower(r. seller_return_reason) like \'%cancel%\' then \'RTO\' when lower(r.Return_Type) like \'%customer%\' then \'return\' when coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) = 1 then \'return\' when lower(r.channel_return_reason) like \'%lost%\' then \'lost\' when lower(r.seller_return_reason) is not null then \'return\' else null end as return_type ,coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) as return_flag ,r.RETURNED_QUANTITY as TOTAL_RETURNED_QUANTITY ,coalesce(r.channel_return_reason,r.seller_return_reason) as return_reason ,e.Payment_mode ,e.selling_price ,r.PRODUCT_NAME as returned_product_name ,REGEXP_EXTRACT(r.sku, r\'_([^_]+)$\') as returned_product_variant ,r.SKU as returned_sku ,r.Total_Credit_Note_Amount as TOTAL_RETURN_AMOUNT ,case when e.return_flag = 1 then e.tax else 0 end as TOTAL_RETURN_TAX ,null as TOTAL_RETURN_AMOUNT_EXCL_TAX ,r.saleorderitemcode as returned_item_saleorderitemcode ,e.order_status as oms_order_status ,CASE WHEN e.pincode LIKE \'1%\' OR e.pincode LIKE \'2%\' THEN \'North Region\' WHEN e.pincode LIKE \'3%\' OR e.pincode LIKE \'4%\' THEN \'West Region\' WHEN e.pincode LIKE \'5%\' OR e.pincode LIKE \'6%\' THEN \'South Region\' WHEN e.pincode LIKE \'7%\' OR e.pincode LIKE \'8%\' THEN \'East Region\' ELSE NULL END AS region ,DATE_DIFF(date(return_initiated_date), date(Delivered_Date), DAY) AS days_from_delivery ,case when upper(e.sku) like \'B%\' then \'BASIXX\' else \'IZF\' end as brand ,e.Image from maplemonk.izf_sales_consolidated e left join maplemonk.easyecom_izf_all_returns r on e.reference_code = r.reference_code and e.saleorderitemcode = r.saleorderitemcode where upper(e.SKU_STYLE) in (select distinct upper(trim(style)) from maplemonk.google_sheets_po_style_lead_time) ; CREATE OR REPLACE TABLE maplemonk.Returns_Data AS WITH deduped_orders AS ( SELECT DISTINCT CAST(order_date AS DATE) AS order_date, sku_style, sku, order_id, CASE WHEN lower(return_type) LIKE \'%return%\' THEN IFNULL(TOTAL_RETURNED_QUANTITY, 0) ELSE 0 END AS return_qty, CASE WHEN lower(return_type) LIKE \'%rto%\' THEN IFNULL(TOTAL_RETURNED_QUANTITY, 0) ELSE 0 END AS rto_qty, IFNULL(order_quantity, 0) AS order_qty FROM izf-wh.maplemonk.izf_returns_consolidated_intermediate WHERE sku IS NOT NULL AND sku <> \'\' ), daily_sku_agg AS ( SELECT order_date, sku_style, sku, SUM(return_qty) AS daily_return_qty, SUM(rto_qty) AS daily_rto_qty, SUM(order_qty) AS daily_order_qty FROM deduped_orders GROUP BY 1, 2, 3 ), unique_skus AS ( SELECT DISTINCT sku, sku_style FROM izf-wh.maplemonk.izf_returns_consolidated_intermediate WHERE sku IS NOT NULL AND sku <> \'\' ), calendar_dates AS ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2024-01-01\', CURRENT_DATE())) AS date_day ), sku_calendar AS ( SELECT c.date_day, u.sku, u.sku_style FROM calendar_dates c CROSS JOIN unique_skus u ) SELECT sc.date_day AS return_date, sc.sku, sc.sku_style, SUM(agg.daily_return_qty) AS RETURNED_QUANTITY_BTW_7_37_DAYS, SUM(agg.daily_rto_qty) AS RTO_QUANTITY_BTW_7_37_DAYS, SUM(agg.daily_order_qty) AS SOLD_QUANTITY_BTW_7_37_DAYS FROM sku_calendar sc LEFT JOIN daily_sku_agg agg ON sc.sku = agg.sku AND sc.sku_style = agg.sku_style AND agg.order_date BETWEEN DATE_SUB(sc.date_day, INTERVAL 36 DAY) AND DATE_SUB(sc.date_day, INTERVAL 7 DAY) GROUP BY 1, 2, 3; Create or replace table izf-wh.maplemonk.izf_returns_consolidated as select rc.*, rd.RETURNED_QUANTITY_BTW_7_37_DAYS, rd.RTO_QUANTITY_BTW_7_37_DAYS, rd.SOLD_QUANTITY_BTW_7_37_DAYS, concat(\'<img src=\"\',sm.style_image,\'\"width=\"70\">\') as Style_Image from izf-wh.maplemonk.izf_returns_consolidated_intermediate rc left join maplemonk.Returns_Data rd ON lower(RD.sku) = lower(rc.sku) AND CAST(rc.order_date AS DATE) = CAST(rd.return_date AS DATE) AND lower(Rc.sku_style) = lower(rd.sku_style) left join (select upper(split(lower(sku), \'-\')[offset(0)]) as style ,max(product_image_url) as style_image from izf-wh.maplemonk.easyecom_izf_product_master group by 1 ) sm on lower(rc.sku_style) = lower(sm.style) ; CREATE OR REPLACE TABLE izf-wh.maplemonk.izf_returns_count_data AS WITH orders AS ( SELECT LAST_DAY(date(order_date), MONTH) AS order_month, DATE_TRUNC(order_Date, MONTH) AS month_first_date, date(order_date) AS order_date, marketplace, sku_style AS style, count(distinct reference_code) AS orders_for_the_month, COUNT(DISTINCT CASE WHEN (return_flag = 1 AND lower(return_request_type) = \'return\') THEN reference_code END) AS total_returned_orders_for_orders_of_month, sum(case when (return_flag=1 AND lower(return_request_type) = \'return\') then 1 else 0 end) AS total_returned_items_for_orders_of_month, sum(case when (return_flag=1 AND lower(return_request_type) = \'return\') then TOTAL_RETURNED_QUANTITY else 0 end) AS total_returned_quantity_for_orders_of_month, count(*) AS total_order_items_for_the_month, sum(order_quantity) AS total_order_quantity_for_the_month, sum(selling_price) AS total_sales FROM izf-wh.maplemonk.izf_returns_consolidated GROUP BY order_month,month_first_date, order_date,marketplace,sku_style ), returns AS ( SELECT LAST_DAY(DATE(return_date), MONTH) AS return_month, date(original_return_request_date) AS return_date, marketplace, sku_style AS style, COUNT(*) AS total_returned_items_received_in_month, count(distinct reference_code) AS returned_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) AS returned_quantity_received_in_month, sum(TOTAL_RETURN_AMOUNT) AS total_returned_sales FROM izf-wh.maplemonk.izf_returns_consolidated WHERE return_flag = 1 AND lower(return_request_type) = \'return\' AND original_return_request_date is not null GROUP BY return_month,return_date,marketplace,sku_style ), rto AS ( SELECT LAST_DAY(DATE(return_date), MONTH) AS return_month, date(return_date) AS return_date, marketplace, sku_style AS style, COUNT(*) AS total_rto_items_received_in_month, count(distinct reference_code) AS rto_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) AS rto_quantity_received_in_month, sum(TOTAL_RETURN_AMOUNT) AS total_returned_rto_sales FROM izf-wh.maplemonk.izf_returns_consolidated WHERE return_flag = 1 AND lower(return_request_type) = \'rto\' AND original_return_request_date is not null GROUP BY return_month,return_date,marketplace,sku_style ) SELECT o.month_first_date, o.marketplace, o.style, o.order_month, o.order_date, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_order_quantity_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, o.total_returned_quantity_for_orders_of_month, rto.total_rto_items_received_in_month, rto.rto_orders_received_in_month, rto.rto_quantity_received_in_month, o.total_sales, r.total_returned_sales, r.return_date, r.total_returned_items_received_in_month, r.returned_orders_received_in_month, r.returned_quantity_received_in_month, concat(\'<img src=\"\',sm.style_image,\'\"width=\"70\">\') AS Style_Image FROM orders o LEFT JOIN returns r ON r.return_date = o.order_date AND r.marketplace = o.marketplace AND r.style = o.style LEFT JOIN rto ON rto.return_date = o.order_date AND rto.marketplace = o.marketplace AND rto.style = o.style LEFT JOIN (SELECT upper(split(lower(sku), \'-\')[offset(0)]) AS style ,max(product_image_url) AS style_image FROM izf-wh.maplemonk.easyecom_izf_product_master GROUP BY 1 ) sm ON lower(o.style) = lower(sm.style) ORDER BY order_date DESC;",
                    "transaction": true
                }
            ) }}
